definition.script:
import groovy.json.JsonSlurperClassic

// Deploys an already staged HPDS dataset (HPDS auth, HPDS open, PSAMA) to the staging stack, the one named by
// environments.next_prod of the stacks.json archived by Retrieve Deployment State. No stack is a parameter.
// Order: validate the keys, take the deployment-state lock (fails fast), read the staging stack, take the stack lock (waits),
// re-check the staged data, deploy. The deployment-state lock is released in the finally block, and only if this build took it.

def authKey = (params.DATA_S3_OBJECT_KEY ?: '').trim()
def openKey = (params.DESTIGMATIZED_DATASET_S3_OBJECT_KEY ?: '').trim()
def genomicKey = (params.GENOMIC_DATASET_S3_OBJECT_KEY ?: '').trim()

// 1. The keys become S3 key segments and parameters of other jobs: only 7 to 40 lowercase hex characters pass.
for (entry in [['DATA_S3_OBJECT_KEY', authKey], ['DESTIGMATIZED_DATASET_S3_OBJECT_KEY', openKey], ['GENOMIC_DATASET_S3_OBJECT_KEY', genomicKey]]) {
    if (!(entry[1] ==~ /[0-9a-f]{7,40}/)) {
        error("${entry[0]} must be a deploy key of 7 to 40 lowercase hex characters, got '${entry[1]}'. Nothing was deployed.")
    }
}

def lockAcquired = false
def stagingStack = ''
def failureText = ''

try {
    timeout(time: 4, unit: 'HOURS') {
        stage('Take the deployment-state lock') {
            // Fails when another deployment holds the lock: nothing is deployed and lockAcquired stays false.
            def retrieved
            try {
                retrieved = build job: 'Retrieve Deployment State'
            } catch (Exception retrieveError) {
                // Not unlocked here: the hold may belong to another deployment. Retrieve can also fail after it put the hold on.
                echo "Retrieve Deployment State did not finish. This build does not unlock. If the log of Retrieve Deployment State shows put-object-legal-hold ran, run Unlock Deployment State by hand; if the lock was already held by another deployment, do nothing."
                throw retrieveError
            }
            lockAcquired = true
            node {
                copyArtifacts filter: 'stacks.json', projectName: 'Retrieve Deployment State', selector: specific("" + retrieved.number)
                def stacks = new JsonSlurperClassic().parseText(readFile('stacks.json'))
                def candidate = stacks?.environments?.next_prod
                if (!(candidate instanceof String) || candidate == 'null' || !(candidate ==~ /[A-Za-z0-9._-]+/)) {
                    error('environments.next_prod in stacks.json is empty, null or not a plain stack name. Nothing was deployed.')
                }
                stagingStack = candidate
            }
            echo "staging stack: ${stagingStack}"
        }
        stage('Deploy to the staging stack') {
            lock("stack-${stagingStack}") {
                node {
                    withEnv(["AUTH_KEY=${authKey}", "OPEN_KEY=${openKey}"]) {
                        sh '''#!/bin/bash
# shellcheck disable=SC2154  # stack_s3_bucket is a global environment variable of this Jenkins
set -eu

# ListBucket on data/* is granted while HeadObject on a missing key may answer 403, so list first.
key_exists() {
    local key="$1" out
    if out=$(aws s3api list-objects-v2 --bucket "${stack_s3_bucket}" --prefix "${key}" --output json 2> /dev/null); then
        # jq 1.6 -e exits 0 on empty input: an empty listing must mean "not there"
        [ -n "${out}" ] || return 1
        printf '%s' "${out}" | jq -e --arg k "${key}" 'any(.Contents[]?; .Key == $k)' > /dev/null
    else
        aws s3api head-object --bucket "${stack_s3_bucket}" --key "${key}" > /dev/null 2>&1
    fi
}

# is_staged <deploy key> <stage prefix> <legacy tar name>: per-file staging writes manifest.tsv last; a legacy tar is one object.
is_staged() {
    key_exists "data/$1/$2manifest.tsv" || key_exists "data/$1/$3.tar"
}

missing=0
if ! is_staged "${AUTH_KEY}" javabins_rekeyed/ javabins_rekeyed; then
    echo "ERROR: auth dataset is not staged: deploy key ${AUTH_KEY}; run HPDS Data - Stage to Stack Bucket" >&2
    missing=1
fi
if ! is_staged "${OPEN_KEY}" destigmatized_javabins_rekeyed/ destigmatized_javabins_rekeyed; then
    echo "ERROR: open dataset is not staged: deploy key ${OPEN_KEY}; run HPDS Data - Stage to Stack Bucket" >&2
    missing=1
fi
if ! key_exists "data/${AUTH_KEY}/fence_mapping.json"; then
    echo "ERROR: data/${AUTH_KEY}/fence_mapping.json is missing; run HPDS Data - Stage to Stack Bucket with HPDS_VARIANT=auth" >&2
    missing=1
fi
if [ "${missing}" != 0 ]; then
    echo "Nothing was deployed." >&2
    exit 1
fi
echo "staged data re-checked in s3://${stack_s3_bucket}: auth ${AUTH_KEY}, open ${OPEN_KEY}, fence_mapping.json"
'''
                    }
                }
                build job: 'PIC-SURE HPDS Auth Deploy', parameters: [
                    [$class: 'StringParameterValue', name: 'TARGET_STACK', value: stagingStack],
                    [$class: 'StringParameterValue', name: 'DATA_S3_OBJECT_KEY', value: authKey],
                    [$class: 'StringParameterValue', name: 'GENOMIC_DATASET_S3_OBJECT_KEY', value: genomicKey]
                ]
                build job: 'PIC-SURE HPDS Open Deploy', parameters: [
                    [$class: 'StringParameterValue', name: 'TARGET_STACK', value: stagingStack],
                    [$class: 'StringParameterValue', name: 'DESTIGMATIZED_DATASET_S3_OBJECT_KEY', value: openKey]
                ]
                build job: 'PIC-SURE Auth Micro App Deploy', parameters: [
                    [$class: 'StringParameterValue', name: 'TARGET_STACK', value: stagingStack],
                    [$class: 'StringParameterValue', name: 'DATASET_S3_OBJECT_KEY', value: authKey]
                ]
            }
        }
    }
} catch (Exception failure) {
    failureText = failure.message ?: failure.toString()
    throw failure
} finally {
    // Only a lock this build took is released. stacks.json was not changed, so Write Stack State is not needed.
    if (lockAcquired) {
        try {
            build job: 'Unlock Deployment State'
        } catch (Exception unlockError) {
            def earlier = failureText ? " The deployment itself failed before: ${failureText}" : ''
            error("Unlock Deployment State failed (${unlockError.message}); the deployment-state lock is still held. Run the job Unlock Deployment State.${earlier}")
        }
    }
}

echo "staging stack ${stagingStack}: HPDS auth, HPDS open, PSAMA deployed"
